{
    return volumes_sync_call(ch, false, deadline_ns);
}
static inline status_t volumes_sync_within(handle_t ch, uint64_t timeout_ns)
{
    return volumes_sync_call(ch, true, timeout_ns);
}
static inline status_t volumes_sync(handle_t ch)
{
    return volumes_sync_call(ch, false, DEADLINE_NEVER);
}

/* volumes_stop_until and _within: idl_t is a deadline, or with idl_within a
 * timeout from when the call starts (the kernel's clock). */
static inline status_t volumes_stop_call(handle_t ch, bool idl_within, uint64_t idl_t)
{
    struct volumes_stop_req idl_q;
    struct volumes_stop_rep idl_r;
    uint32_t idl_n = 0;
    idl_q.txid = 0;
    idl_q.ordinal = VOLUMES_STOP;
    status_t idl_st = idl_call(ch, &idl_q, sizeof(idl_q), &idl_r, sizeof(idl_r), &idl_n, NULL, 0,
                               NULL, idl_within, idl_t);
    if (idl_st == OK)
        idl_st = idl_rep_status(&idl_r, idl_n, sizeof(idl_r));
    return idl_st;
}
/* Stop, for a reboot: every writable mount synced, then every filesystem
 * service stopped (and the warm spare); answered then, and volumes exits
 * (0 if nothing went wrong while it ran). Requests after it: the channel
 * closes. */
static inline status_t volumes_stop_until(handle_t ch, uint64_t deadline_ns)
{
    return volumes_stop_call(ch, false, deadline_ns);
}
static inline status_t volumes_stop_within(handle_t ch, uint64_t timeout_ns)
{
    return volumes_stop_call(ch, true, timeout_ns);
}
static inline status_t volumes_stop(handle_t ch)
{
    return volumes_stop_call(ch, false, DEADLINE_NEVER);
}

/* volumes_set_disks_until and _within: idl_t is a deadline, or with idl_within a
 * timeout from when the call starts (the kernel's clock). */
static inline status_t volumes_set_disks_call(handle_t ch, bool idl_within, uint64_t idl_t, handle_t disks)
{
    _Alignas(8) uint8_t idl_b0[8];
    _Alignas(8) uint8_t idl_b1[8];
    struct volumes_set_disks_req *idl_q = (struct volumes_set_disks_req *)idl_b0;
    const struct volumes_set_disks_rep *idl_r = (const struct volumes_set_disks_rep *)idl_b1;
    uint32_t idl_qn = sizeof(*idl_q), idl_o = sizeof(*idl_r);
    uint32_t idl_got[2] = { 0, 0 };   /* bytes, handles: in a row, one copy-out */
    status_t idl_st = OK;
    idl_q->txid = 0;
    idl_q->ordinal = VOLUMES_SET_DISKS;
    handle_t idl_wh[1];
    uint32_t idl_wn = 0;
    if (idl_st == OK) {
        idl_wh[idl_wn++] = disks;
        idl_st = idl_call_h(ch, idl_b0, idl_qn, idl_wh, idl_wn, idl_b1, 8, &idl_got[0], NULL, 0, &idl_got[1],
                            idl_within, idl_t);
    } else {   /* never sent: the handles are still ours */
        if (disks != HANDLE_INVALID)
            drv_handle_close(disks);
    }
    if (idl_st == OK)
        idl_st = idl_rep_status(idl_b1, idl_got[0], sizeof(*idl_r));
    (void)idl_o;
    return idl_st;
}
/* The server end of a new disks channel (devmgr was started again, and
 * init made the pair). The disks of the old one are forgotten, without
 * notices. */
static inline status_t volumes_set_disks_until(handle_t ch, uint64_t deadline_ns, handle_t disks)
{
    return volumes_set_disks_call(ch, false, deadline_ns, disks);
}
static inline status_t volumes_set_disks_within(handle_t ch, uint64_t timeout_ns, handle_t disks)
{
    return volumes_set_disks_call(ch, true, timeout_ns, disks);
}
static inline status_t volumes_set_disks(handle_t ch, handle_t disks)
{
    return volumes_set_disks_call(ch, false, DEADLINE_NEVER, disks);
}

