/* volumes_watch without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then volumes_watch_result. */
static inline status_t volumes_watch_send(handle_t ch, uint32_t idl_txid)
{
    if (!idl_txid)
        return ERR_INVALID_ARGS;
    _Alignas(8) uint8_t idl_b0[8];
    struct volumes_watch_req *idl_q = (struct volumes_watch_req *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = idl_txid;
    idl_q->ordinal = VOLUMES_WATCH;
    if (idl_st == OK)
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, NULL, 0);
    return idl_st;
}

/* The status and results of a reply to volumes_watch_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t volumes_watch_result(const void *idl_rep, struct idl_msg *idl_m, handle_t *out_events)
{
    const struct volumes_watch_rep *idl_r = (const struct volumes_watch_rep *)idl_rep;
    status_t idl_st = idl_rep_status(idl_rep, idl_m->n, sizeof(*idl_r));
    if (idl_st == OK && idl_m->nh != 1)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(idl_handle_is(idl_m->hs[0], IDL_OBJ_CHANNEL)))
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    if (out_events)
        *out_events = idl_m->hs[0];
    else
        drv_handle_close(idl_m->hs[0]);
    idl_m->nh = 0;
    return OK;
}

