/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with volumes_reply_<method> (now, or later from anywhere). */
struct volumes_ops {
    status_t (*watch)(void *ctx, handle_t *out_events);
    status_t (*remount)(void *ctx, struct idl_txn idl_txn, const char *mount, uint32_t mount_len, uint8_t writable);
    status_t (*kill)(void *ctx, struct idl_txn idl_txn, const char *mount, uint32_t mount_len, uint64_t *out_koid);
    status_t (*supervision)(void *ctx, const char *mount, uint32_t mount_len, uint32_t *out_state, uint32_t *out_restarts, uint32_t *out_backoff_ms, uint32_t *out_promoted, uint8_t *out_spare_waits);
    status_t (*test_disk)(void *ctx, handle_t storage, uint32_t *out_id);
    status_t (*release_disk)(void *ctx, struct idl_txn idl_txn, uint32_t id);
    status_t (*sync)(void *ctx, struct idl_txn idl_txn);
    status_t (*stop)(void *ctx, struct idl_txn idl_txn);
    status_t (*set_disks)(void *ctx, handle_t disks);
};

/* Answer the volumes.watch request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t volumes_reply_watch(struct idl_txn idl_txn, status_t idl_st, handle_t events)
{
    handle_t idl_hs[1] = { events };
    _Alignas(8) uint8_t idl_b0[8];
    struct volumes_watch_rep *idl_r = (struct volumes_watch_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(events != HANDLE_INVALID))
        idl_st = ERR_INTERNAL;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        if (idl_hs[0] != HANDLE_INVALID)
            drv_handle_close(idl_hs[0]);
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, idl_st == OK ? idl_hs : NULL, idl_st == OK ? 1 : 0);
    return idl_ws;
}

/* Answer the volumes.remount request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t volumes_reply_remount(struct idl_txn idl_txn, status_t idl_st)
{
    _Alignas(8) uint8_t idl_b0[8];
    struct volumes_remount_rep *idl_r = (struct volumes_remount_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, NULL, 0);
    return idl_ws;
}

/* Answer the volumes.kill request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t volumes_reply_kill(struct idl_txn idl_txn, status_t idl_st, uint64_t koid)
{
    _Alignas(8) uint8_t idl_b0[16];
    struct volumes_kill_rep *idl_r = (struct volumes_kill_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r->koid = koid;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, NULL, 0);
    return idl_ws;
}

