/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (VOLUMES_REP_MAX bytes) and the handles it carries
 * into rhs (VOLUMES_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it.
 * The idl_nh handles at idl_hs (the call's arguments) are taken in every
 * case: given to its handler, or closed (the handler owns them, whatever it
 * returns). */
static inline uint32_t volumes_dispatch_h(handle_t ch, const struct volumes_ops *ops, void *ctx,
                                          const void *req, uint32_t n, const handle_t *idl_hs, uint32_t idl_nh,
                                          void *rep, handle_t *rhs, uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    if (n < sizeof(uint32_t)) {
        idl_close_all(idl_hs, idl_nh);
        return 0;
    }
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr)) {
        idl_close_all(idl_hs, idl_nh);
        return sizeof(*idl_h);
    }
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case VOLUMES_WATCH: {
        const struct volumes_watch_req *idl_q = (const struct volumes_watch_req *)req;
        struct volumes_watch_rep *idl_r = (struct volumes_watch_rep *)rep;
        handle_t out_events = HANDLE_INVALID;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->watch) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->watch(ctx, &out_events);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_events != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_events != HANDLE_INVALID)
                drv_handle_close(out_events);
            return sizeof(*idl_h);
        }
        rhs[0] = out_events;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case VOLUMES_REMOUNT: {
        const struct volumes_remount_req *idl_q = (const struct volumes_remount_req *)req;
        struct volumes_remount_rep *idl_r = (struct volumes_remount_rep *)rep;
        (void)idl_r;
        uint32_t idl_o = sizeof(*idl_q);
        status_t idl_st = n < sizeof(*idl_q) ? ERR_INVALID_ARGS : OK;
        const void *idl_p0 = NULL;
        uint32_t idl_l0 = 0;
        if (idl_st == OK && !idl_get(req, n, &idl_o, 15, 1, &idl_p0, &idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_o != n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->remount) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        idl_st = ops->remount(ctx, idl_txn, (const char *)idl_p0, idl_l0, idl_q->writable);
        /* IDL_LATER: the handler answers with volumes_reply_remount. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case VOLUMES_KILL: {
        const struct volumes_kill_req *idl_q = (const struct volumes_kill_req *)req;
        struct volumes_kill_rep *idl_r = (struct volumes_kill_rep *)rep;
        uint64_t out_koid = 0;
        uint32_t idl_o = sizeof(*idl_q);
        status_t idl_st = n < sizeof(*idl_q) ? ERR_INVALID_ARGS : OK;
        const void *idl_p0 = NULL;
        uint32_t idl_l0 = 0;
        if (idl_st == OK && !idl_get(req, n, &idl_o, 15, 1, &idl_p0, &idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_o != n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->kill) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        idl_st = ops->kill(ctx, idl_txn, (const char *)idl_p0, idl_l0, &out_koid);
        /* IDL_LATER: the handler answers with volumes_reply_kill. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->koid = out_koid;
        return sizeof(*idl_r);
    }
    case VOLUMES_SUPERVISION: {
        const struct volumes_supervision_req *idl_q = (const struct volumes_supervision_req *)req;
        struct volumes_supervision_rep *idl_r = (struct volumes_supervision_rep *)rep;
        uint32_t out_state = 0;
        uint32_t out_restarts = 0;
        uint32_t out_backoff_ms = 0;
        uint32_t out_promoted = 0;
        uint8_t out_spare_waits = 0;
        uint32_t idl_o = sizeof(*idl_q);
        status_t idl_st = n < sizeof(*idl_q) ? ERR_INVALID_ARGS : OK;
        const void *idl_p0 = NULL;
        uint32_t idl_l0 = 0;
        if (idl_st == OK && !idl_get(req, n, &idl_o, 15, 1, &idl_p0, &idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_o != n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->supervision) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        idl_st = ops->supervision(ctx, (const char *)idl_p0, idl_l0, &out_state, &out_restarts, &out_backoff_ms, &out_promoted, &out_spare_waits);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->state = out_state;
        idl_r->restarts = out_restarts;
        idl_r->backoff_ms = out_backoff_ms;
        idl_r->promoted = out_promoted;
        idl_r->spare_waits = out_spare_waits;
        return sizeof(*idl_r);
    }
    case VOLUMES_TEST_DISK: {
        const struct volumes_test_disk_req *idl_q = (const struct volumes_test_disk_req *)req;
        struct volumes_test_disk_rep *idl_r = (struct volumes_test_disk_rep *)rep;
        uint32_t out_id = 0;
        if (n != sizeof(*idl_q) || idl_nh != 1) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->test_disk) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        if (!(idl_handle_is(idl_hs[0], IDL_OBJ_CHANNEL))) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_WRONG_TYPE;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->test_disk(ctx, idl_hs[0], &out_id);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->id = out_id;
        return sizeof(*idl_r);
    }
    case VOLUMES_RELEASE_DISK: {
        const struct volumes_release_disk_req *idl_q = (const struct volumes_release_disk_req *)req;
        struct volumes_release_disk_rep *idl_r = (struct volumes_release_disk_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->release_disk) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->release_disk(ctx, idl_txn, idl_q->id);
        /* IDL_LATER: the handler answers with volumes_reply_release_disk. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case VOLUMES_SYNC: {
        const struct volumes_sync_req *idl_q = (const struct volumes_sync_req *)req;
        struct volumes_sync_rep *idl_r = (struct volumes_sync_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->sync) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->sync(ctx, idl_txn);
        /* IDL_LATER: the handler answers with volumes_reply_sync. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case VOLUMES_STOP: {
        const struct volumes_stop_req *idl_q = (const struct volumes_stop_req *)req;
        struct volumes_stop_rep *idl_r = (struct volumes_stop_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->stop) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->stop(ctx, idl_txn);
        /* IDL_LATER: the handler answers with volumes_reply_stop. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case VOLUMES_SET_DISKS: {
        const struct volumes_set_disks_req *idl_q = (const struct volumes_set_disks_req *)req;
        struct volumes_set_disks_rep *idl_r = (struct volumes_set_disks_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q) || idl_nh != 1) {
            idl_close_all(idl_hs, idl_nh);
            return sizeof(*idl_h);
        }
        if (!ops->set_disks) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        if (!(idl_handle_is(idl_hs[0], IDL_OBJ_CHANNEL))) {
            idl_close_all(idl_hs, idl_nh);
            idl_h->status = ERR_WRONG_TYPE;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_disks(ctx, idl_hs[0]);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    }
    idl_close_all(idl_hs, idl_nh);
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* volumes_dispatch_h without handles (a loop of your own that reads none:
 * an event or call that takes some is then refused). */
static inline uint32_t volumes_dispatch_on(handle_t ch, const struct volumes_ops *ops, void *ctx,
                                           const void *req, uint32_t n, void *rep, handle_t *rhs,
                                           uint32_t *rhn)
{
    return volumes_dispatch_h(ch, ops, ctx, req, n, NULL, 0, rep, rhs, rhn);
}

/* volumes_dispatch_on without the channel (a `later` handler's txn then has none: use volumes_dispatch_on). */
static inline uint32_t volumes_dispatch(const struct volumes_ops *ops, void *ctx, const void *req, uint32_t n,
                                        void *rep, handle_t *rhs, uint32_t *rhn)
{
    return volumes_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t volumes_take_slot(handle_t ch, const struct idl_slot *slot,
                                         struct idl_reply *rep)
{
    if (slot->qcap < VOLUMES_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the message in slot (taken by volumes_take_slot, or found there by a
 * successor), which came on ch: as volumes_dispatch_h, its reply built in
 * slot->r and the handles that reply carries put into rhs
 * (VOLUMES_REP_HANDLES slots; *rhn of them). The handles it carried
 * (*slot->nh in slot->hs) are taken: given to a handler or closed,
 * *slot->nh 0 after. Returns the reply's length: 0 means no reply
 * (no txid, an event, or a `later` handler answers it itself). No I/O;
 * the caller sends the reply with the handles, or closes them if it
 * never sends it. */
static inline uint32_t volumes_run_slot(handle_t ch, const struct idl_slot *slot,
                                        const struct volumes_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    uint32_t idl_nh = *slot->nh;
    *slot->nh = 0;
    return volumes_dispatch_h(ch, ops, ctx, slot->q, *slot->n, slot->hs, idl_nh, slot->r,
                          rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool volumes_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t volumes_serve_one(handle_t ch, const struct volumes_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[VOLUMES_REQ_MAX];
    _Alignas(8) uint8_t idl_r[VOLUMES_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, VOLUMES_REQ_MAX, &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL) {
        idl_st = idl_drain(ch, idl_n, idl_nh);
    } else if (idl_st == OK) {
        handle_t idl_rhs[IDL_REP_HANDLES];
        uint32_t idl_rhn = 0;
        uint32_t idl_rn = volumes_dispatch_h(ch, ops, ctx, idl_q, idl_n, idl_hs, idl_nh, idl_r,
                                         idl_rhs, &idl_rhn);
        if (!idl_rn)
            idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
        else   /* the reply's handles are gone whatever the write's status */
            (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    }
    return idl_st;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t volumes_serve(handle_t ch, const struct volumes_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[VOLUMES_REQ_MAX];
    _Alignas(8) uint8_t idl_r[VOLUMES_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES], idl_hs[IDL_READ_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = VOLUMES_REQ_MAX, .r = idl_r, .rhs = idl_rhs,
        .hs = idl_hs, .hcap = IDL_READ_HANDLES,
    };
    status_t idl_st;
    while ((idl_st = idl_serve_next(&idl_s)) == OK)
        idl_s.rn = volumes_dispatch_h(ch, ops, ctx, idl_q, idl_s.n, idl_hs, idl_s.nh, idl_r,
                                  idl_rhs, &idl_s.rhn);
    return idl_st == ERR_PEER_CLOSED ? OK : idl_st;
}


/* ==== protocol `volesp` (id 71) =============================================
 *
 * volesp: the boot disk's ESP made writable, for init's stick write
 * (`update -w`, user/services/init/espwrite.c) alone: init made this
 * channel when it started volumes, and gives it to nobody; volumes serves
 * nothing else on it, and nothing of this on any other channel. While
 * writable, /esp is no mount (every watch is told `unmounted`), so no
 * namespace holds the writable channel.
 *
 * Reconnect: ERR_PEER_CLOSED: volumes ended; the ESP is read-only again
 * with the next volumes, and init has a new ESP channel for it. */

#define VOLESP_PROTOCOL_ID 71u
#define VOLESP_OPEN_WRITABLE    0x00470001u
#define VOLESP_CLOSE_WRITABLE   0x00470002u

/* Messages (packed: no padding bytes ever cross the channel). */
struct volesp_open_writable_req {
    uint32_t txid;
    uint32_t ordinal;
} __attribute__((packed));
struct volesp_open_writable_rep {
    uint32_t txid;
    int32_t  status;
} __attribute__((packed));
struct volesp_close_writable_req {
    uint32_t txid;
    uint32_t ordinal;
} __attribute__((packed));
struct volesp_close_writable_rep {
    uint32_t txid;
    int32_t  status;
} __attribute__((packed));

#define VOLESP_REQ_MAX 8u   /* bytes: the biggest request */
#define VOLESP_REP_MAX 8u   /* bytes: the biggest reply */
#define VOLESP_REQ_HANDLES IDL_READ_HANDLES   /* handles: read with each message to the server */
#define VOLESP_REP_HANDLES IDL_REP_HANDLES   /* handles: room in a dispatch's rhs */

/* ---- client ---------------------------------------------------------- */

/* volesp_open_writable_until and _within: idl_t is a deadline, or with idl_within a
 * timeout from when the call starts (the kernel's clock). */
static inline status_t volesp_open_writable_call(handle_t ch, bool idl_within, uint64_t idl_t, handle_t *out_fs)
{
    _Alignas(8) uint8_t idl_b0[8];
    _Alignas(8) uint8_t idl_b1[8];
    struct volesp_open_writable_req *idl_q = (struct volesp_open_writable_req *)idl_b0;
    const struct volesp_open_writable_rep *idl_r = (const struct volesp_open_writable_rep *)idl_b1;
    uint32_t idl_qn = sizeof(*idl_q), idl_o = sizeof(*idl_r);
    uint32_t idl_got[2] = { 0, 0 };   /* bytes, handles: in a row, one copy-out */
    status_t idl_st = OK;
    idl_q->txid = 0;
    idl_q->ordinal = VOLESP_OPEN_WRITABLE;
    handle_t idl_rh[1];
    if (idl_st == OK)
        idl_st = idl_call(ch, idl_b0, idl_qn, idl_b1, 8, &idl_got[0], idl_rh, 1, &idl_got[1],
                          idl_within, idl_t);
    if (idl_st != OK)
        idl_got[1] = 0;   /* handles arrive only with OK */
    if (idl_st == OK)
        idl_st = idl_rep_status(idl_b1, idl_got[0], sizeof(*idl_r));
    if (idl_st == OK && idl_got[1] != 1)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(idl_handle_is(idl_rh[0], IDL_OBJ_CHANNEL)))
        idl_st = ERR_INTERNAL;
    if (idl_st != OK)
        idl_close_all(idl_rh, idl_got[1]);
    if (idl_st == OK) {
        if (out_fs)
            *out_fs = idl_rh[0];
        else
            drv_handle_close(idl_rh[0]);
    }
    (void)idl_o;
    return idl_st;
}
/* The ESP's service stops in order and starts again on a `block` channel
 * opened read-write; `fs` is a channel to it, the caller's alone. Called
 * while it is writable already: another handle to the same channel. A
 * crash meanwhile restarts it writable; a pulled stick ends it (the
 * stick's next mount is read-only). ERR_NOT_FOUND: no boot disk with an
 * ESP service; ERR_BAD_STATE: it isn't serving. */
static inline status_t volesp_open_writable_until(handle_t ch, uint64_t deadline_ns, handle_t *out_fs)
{
    return volesp_open_writable_call(ch, false, deadline_ns, out_fs);
}
static inline status_t volesp_open_writable_within(handle_t ch, uint64_t timeout_ns, handle_t *out_fs)
{
    return volesp_open_writable_call(ch, true, timeout_ns, out_fs);
}
static inline status_t volesp_open_writable(handle_t ch, handle_t *out_fs)
{
    return volesp_open_writable_call(ch, false, DEADLINE_NEVER, out_fs);
}

/* volesp_close_writable_until and _within: idl_t is a deadline, or with idl_within a
 * timeout from when the call starts (the kernel's clock). */
static inline status_t volesp_close_writable_call(handle_t ch, bool idl_within, uint64_t idl_t)
{
    struct volesp_close_writable_req idl_q;
    struct volesp_close_writable_rep idl_r;
    uint32_t idl_n = 0;
    idl_q.txid = 0;
    idl_q.ordinal = VOLESP_CLOSE_WRITABLE;
    status_t idl_st = idl_call(ch, &idl_q, sizeof(idl_q), &idl_r, sizeof(idl_r), &idl_n, NULL, 0,
                               NULL, idl_within, idl_t);
    if (idl_st == OK)
        idl_st = idl_rep_status(&idl_r, idl_n, sizeof(idl_r));
    return idl_st;
}
/* Back to read-only: it stops in order (everything on the stick, the
 * volume clean), starts again read-only, and /esp is a mount again (a new
 * channel). OK at once if it is read-only already. */
static inline status_t volesp_close_writable_until(handle_t ch, uint64_t deadline_ns)
{
    return volesp_close_writable_call(ch, false, deadline_ns);
}
static inline status_t volesp_close_writable_within(handle_t ch, uint64_t timeout_ns)
{
    return volesp_close_writable_call(ch, true, timeout_ns);
}
static inline status_t volesp_close_writable(handle_t ch)
{
    return volesp_close_writable_call(ch, false, DEADLINE_NEVER);
}

/* ---- client, asynchronous (tools/genidl.py) --------------------------- */

/* volesp_open_writable without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then volesp_open_writable_result. */
static inline status_t volesp_open_writable_send(handle_t ch, uint32_t idl_txid)
{
    if (!idl_txid)
        return ERR_INVALID_ARGS;
    _Alignas(8) uint8_t idl_b0[8];
    struct volesp_open_writable_req *idl_q = (struct volesp_open_writable_req *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = idl_txid;
    idl_q->ordinal = VOLESP_OPEN_WRITABLE;
    if (idl_st == OK)
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, NULL, 0);
    return idl_st;
}

/* The status and results of a reply to volesp_open_writable_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t volesp_open_writable_result(const void *idl_rep, struct idl_msg *idl_m, handle_t *out_fs)
{
    const struct volesp_open_writable_rep *idl_r = (const struct volesp_open_writable_rep *)idl_rep;
    status_t idl_st = idl_rep_status(idl_rep, idl_m->n, sizeof(*idl_r));
    if (idl_st == OK && idl_m->nh != 1)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(idl_handle_is(idl_m->hs[0], IDL_OBJ_CHANNEL)))
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    if (out_fs)
        *out_fs = idl_m->hs[0];
    else
        drv_handle_close(idl_m->hs[0]);
    idl_m->nh = 0;
    return OK;
}

/* volesp_close_writable without waiting: the request, with the caller's txid (not 0).
 * The reply comes on ch: idl_reply_read, then volesp_close_writable_result. */
static inline status_t volesp_close_writable_send(handle_t ch, uint32_t idl_txid)
{
    struct volesp_close_writable_req idl_q;
    if (!idl_txid)
        return ERR_INVALID_ARGS;
    idl_q.txid = idl_txid;
    idl_q.ordinal = VOLESP_CLOSE_WRITABLE;
    return drv_channel_write(ch, &idl_q, sizeof(idl_q), NULL, 0);
}

/* The status and results of a reply to volesp_close_writable_send (read with
 * idl_reply_read). The reply's handles are taken in every case: moved to
 * the results, or closed (on a failure, or for a NULL result). */
static inline status_t volesp_close_writable_result(const void *idl_rep, struct idl_msg *idl_m)
{
    const struct volesp_close_writable_rep *idl_r = (const struct volesp_close_writable_rep *)idl_rep;
    status_t idl_st = idl_rep_status(idl_rep, idl_m->n, sizeof(*idl_r));
    if (idl_st == OK && idl_m->nh != 0)
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    idl_m->nh = 0;
    (void)idl_r;
    return OK;
}

/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with volesp_reply_<method> (now, or later from anywhere). */
struct volesp_ops {
    status_t (*open_writable)(void *ctx, struct idl_txn idl_txn, handle_t *out_fs);
    status_t (*close_writable)(void *ctx, struct idl_txn idl_txn);
};

/* Answer the volesp.open_writable request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t volesp_reply_open_writable(struct idl_txn idl_txn, status_t idl_st, handle_t fs)
{
    handle_t idl_hs[1] = { fs };
    _Alignas(8) uint8_t idl_b0[8];
    struct volesp_open_writable_rep *idl_r = (struct volesp_open_writable_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !(fs != HANDLE_INVALID))
        idl_st = ERR_INTERNAL;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        if (idl_hs[0] != HANDLE_INVALID)
            drv_handle_close(idl_hs[0]);
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, idl_st == OK ? idl_hs : NULL, idl_st == OK ? 1 : 0);
    return idl_ws;
}

/* Answer the volesp.close_writable request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t volesp_reply_close_writable(struct idl_txn idl_txn, status_t idl_st)
{
    struct volesp_close_writable_rep idl_r;
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r.status = idl_st;
    if (idl_st != OK)
        return idl_reply_write(idl_txn, &idl_r, sizeof(struct idl_rep_hdr), NULL, 0);
    return idl_reply_write(idl_txn, &idl_r, sizeof(idl_r), NULL, 0);
}

/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (VOLESP_REP_MAX bytes) and the handles it carries
 * into rhs (VOLESP_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it. */
static inline uint32_t volesp_dispatch_on(handle_t ch, const struct volesp_ops *ops, void *ctx,
                                          const void *req, uint32_t n, void *rep, handle_t *rhs,
                                          uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case VOLESP_OPEN_WRITABLE: {
        const struct volesp_open_writable_req *idl_q = (const struct volesp_open_writable_req *)req;
        struct volesp_open_writable_rep *idl_r = (struct volesp_open_writable_rep *)rep;
        handle_t out_fs = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->open_writable) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->open_writable(ctx, idl_txn, &out_fs);
        /* IDL_LATER: the handler answers with volesp_reply_open_writable. */
        if (idl_st == IDL_LATER) {
            if (out_fs != HANDLE_INVALID)
                drv_handle_close(out_fs);
            return 0;
        }
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_fs != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_fs != HANDLE_INVALID)
                drv_handle_close(out_fs);
            return sizeof(*idl_h);
        }
        rhs[0] = out_fs;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case VOLESP_CLOSE_WRITABLE: {
        const struct volesp_close_writable_req *idl_q = (const struct volesp_close_writable_req *)req;
        struct volesp_close_writable_rep *idl_r = (struct volesp_close_writable_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->close_writable) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->close_writable(ctx, idl_txn);
        /* IDL_LATER: the handler answers with volesp_reply_close_writable. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* volesp_dispatch_on without the channel (a `later` handler's txn then has none: use volesp_dispatch_on). */
static inline uint32_t volesp_dispatch(const struct volesp_ops *ops, void *ctx, const void *req, uint32_t n,
                                       void *rep, handle_t *rhs, uint32_t *rhn)
{
    return volesp_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t volesp_take_slot(handle_t ch, const struct idl_slot *slot,
                                        struct idl_reply *rep)
{
    if (slot->qcap < VOLESP_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by volesp_take_slot, or found there by a
 * successor), which came on ch: as volesp_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (VOLESP_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it never sends it. */
static inline uint32_t volesp_run_slot(handle_t ch, const struct idl_slot *slot,
                                       const struct volesp_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return volesp_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool volesp_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t volesp_serve_one(handle_t ch, const struct volesp_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[VOLESP_REQ_MAX];
    _Alignas(8) uint8_t idl_r[VOLESP_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = volesp_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn)
        idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
    else   /* the reply's handles are gone whatever the write's status */
        (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t volesp_serve(handle_t ch, const struct volesp_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[VOLESP_REQ_MAX];
    _Alignas(8) uint8_t idl_r[VOLESP_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = volesp_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}


/* ==== protocol `disks` (id 72) ==============================================
 *
 * disks: the disks devmgr's drivers serve, told to volumes (devmgr's
 * user/services/devmgr/disks.c sends, volumes serves). init makes a new
 * pair whenever devmgr or volumes starts, and hands one end to each
 * (devmgr's SET_VOLUMES; volumes' startup role or `volumes.set_disks`).
 * One way: devmgr waits for nothing.
 *
 * Reconnect: when the channel's peer closes, the other side drops it and
 * waits for the next: devmgr announces every disk again on a new channel;
 * volumes forgets every disk the old one announced, without notices. */

#define DISKS_PROTOCOL_ID 72u
#define DISKS_ATTACH           0x00480001u
#define DISKS_GONE             0x00480002u

/* Constants (the .idl's `const` lines). */
/* Buses (attach's `bus`). */
#define DISKS_BUS_USB 1u
#define DISKS_BUS_NVME 2u

/* Messages (packed: no padding bytes ever cross the channel). */
struct disks_attach_msg {   /* an event: txid 0 */
    uint32_t txid;
    uint32_t ordinal;
    uint32_t id;
    uint8_t bus;
} __attribute__((packed));
struct disks_gone_msg {   /* an event: txid 0 */
    uint32_t txid;
    uint32_t ordinal;
    uint32_t id;
} __attribute__((packed));

#define DISKS_REQ_MAX 13u   /* bytes: the biggest message to the server */
#define DISKS_REP_MAX 8u   /* bytes: the biggest message to the client */
#define DISKS_REQ_HANDLES IDL_READ_HANDLES   /* handles: read with each message to the server */
#define DISKS_REP_HANDLES IDL_REP_HANDLES   /* handles: room in a dispatch's rhs */

/* ---- client ---------------------------------------------------------- */

/* ---- client, asynchronous (tools/genidl.py) --------------------------- */

/* ---- events (one way, txid 0, never answered) -------------------------- */

/* A disk is there: its driver runs. `storage` is a channel of volumes'
 * own (devmgr asked the driver's DR_SERVE for it: svc.connect). `id` names
 * the disk while the device is there (USB: usb-bus's device id; a later
 * bus picks ids in its own range, never with the top bit, which test
 * disks use). A driver started again after a crash is announced again
 * with the same id. ERR_PEER_CLOSED on `storage` alone means the driver
 * ended, not that the device went. */
/* The event disks.attach, to the server: written on ch, never answered.
 * ERR_SHOULD_WAIT: the peer's queue is full (its flow control).
 * The handles are gone in every case: sent, closed, or lost with a
 * write that failed (the caller never closes them after this). */
static inline status_t disks_attach(handle_t ch, uint32_t id, uint8_t bus, handle_t storage)
{
    _Alignas(8) uint8_t idl_b0[13];
    struct disks_attach_msg *idl_q = (struct disks_attach_msg *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = 0;   /* an event */
    idl_q->ordinal = DISKS_ATTACH;
    idl_q->id = id;
    idl_q->bus = bus;
    handle_t idl_hs[1];
    uint32_t idl_hn = 0;
    if (idl_st == OK) {
        idl_hs[idl_hn++] = storage;
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, idl_hs, idl_hn);
    } else {   /* never sent: the handles are still ours */
        if (storage != HANDLE_INVALID)
            drv_handle_close(storage);
    }
    return idl_st;
}

/* The device is gone (unplugged, or its bus driver ended): the disk will
 * not come back under this id. */
/* The event disks.gone, to the server: written on ch, never answered.
 * ERR_SHOULD_WAIT: the peer's queue is full (its flow control). */
static inline status_t disks_gone(handle_t ch, uint32_t id)
{
    _Alignas(8) uint8_t idl_b0[12];
    struct disks_gone_msg *idl_q = (struct disks_gone_msg *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = 0;   /* an event */
    idl_q->ordinal = DISKS_GONE;
    idl_q->id = id;
    if (idl_st == OK)
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, NULL, 0);
    return idl_st;
}

/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with disks_reply_<method> (now, or later from anywhere). An event's
 * handler returns nothing (nothing is answered; a NULL one drops it),
 * owns the handles it is given, and its arrays point into the message. */
struct disks_ops {
    void (*attach)(void *ctx, uint32_t id, uint8_t bus, handle_t storage);
    void (*gone)(void *ctx, uint32_t id);
};

/* Run the event (txid 0) of n bytes at m with nh handles in hs: OK, or
 * ERR_NOT_SUPPORTED (no such event, or no handler) or ERR_INVALID_ARGS
 * (it breaks the event's format), its handles closed. */
static inline status_t disks_event_in(const struct disks_ops *idl_tab, void *ctx,
                                      const void *idl_m, uint32_t idl_n, const handle_t *idl_hs, uint32_t idl_nh)
{
    switch (((const struct idl_req_hdr *)idl_m)->ordinal) {
    case DISKS_ATTACH: {
        const struct disks_attach_msg *idl_e = (const struct disks_attach_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        if (idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 1)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->attach)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st == OK && !(idl_handle_is(idl_hs[0], IDL_OBJ_CHANNEL)))
            idl_st = ERR_WRONG_TYPE;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->attach(ctx, idl_e->id, idl_e->bus, idl_hs[0]);
        return OK;
    }
    case DISKS_GONE: {
        const struct disks_gone_msg *idl_e = (const struct disks_gone_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        if (idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 0)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->gone)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->gone(ctx, idl_e->id);
        return OK;
    }
    }
    idl_close_all(idl_hs, idl_nh);
    return ERR_NOT_SUPPORTED;
}

/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (DISKS_REP_MAX bytes) and the handles it carries
 * into rhs (DISKS_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the message has no txid, a `later` handler
 * answers it itself, or it is an event: txid 0, never answered; one no
 * handler takes is dropped). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it.
 * The idl_nh handles at idl_hs (an event's, or a call's arguments) are taken
 * in every case: given to the handler, or closed. */
static inline uint32_t disks_dispatch_h(handle_t ch, const struct disks_ops *ops, void *ctx,
                                        const void *req, uint32_t n, const handle_t *idl_hs, uint32_t idl_nh,
                                        void *rep, handle_t *rhs, uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(struct idl_req_hdr) || !((const struct idl_req_hdr *)req)->txid) {
        /* txid 0: an event (or no txid): never answered */
        if (n >= sizeof(struct idl_req_hdr))
            (void)disks_event_in(ops, ctx, req, n, idl_hs, idl_nh);
        else
            idl_close_all(idl_hs, idl_nh);
        return 0;
    }
    if (idl_nh) {   /* a request with handles: only an event takes any */
        idl_close_all(idl_hs, idl_nh);
        idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
        idl_h->status = ERR_INVALID_ARGS;
        return sizeof(*idl_h);
    }
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case DISKS_ATTACH:
    case DISKS_GONE:
        return sizeof(*idl_h);   /* an event with a txid */
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* disks_dispatch_h without handles (a loop of your own that reads none:
 * an event or call that takes some is then refused). */
static inline uint32_t disks_dispatch_on(handle_t ch, const struct disks_ops *ops, void *ctx,
                                         const void *req, uint32_t n, void *rep, handle_t *rhs,
                                         uint32_t *rhn)
{
    return disks_dispatch_h(ch, ops, ctx, req, n, NULL, 0, rep, rhs, rhn);
}

/* disks_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t disks_dispatch(const struct disks_ops *ops, void *ctx, const void *req, uint32_t n,
                                      void *rep, handle_t *rhs, uint32_t *rhn)
{
    return disks_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t disks_take_slot(handle_t ch, const struct idl_slot *slot,
                                       struct idl_reply *rep)
{
    if (slot->qcap < DISKS_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the message in slot (taken by disks_take_slot, or found there by a
 * successor), which came on ch: as disks_dispatch_h, its reply built in
 * slot->r and the handles that reply carries put into rhs
 * (DISKS_REP_HANDLES slots; *rhn of them). The handles it carried
 * (*slot->nh in slot->hs) are taken: given to a handler or closed,
 * *slot->nh 0 after. Returns the reply's length: 0 means no reply
 * (no txid, an event, or a `later` handler answers it itself). No I/O;
 * the caller sends the reply with the handles, or closes them if it
 * never sends it. */
static inline uint32_t disks_run_slot(handle_t ch, const struct idl_slot *slot,
                                      const struct disks_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    uint32_t idl_nh = *slot->nh;
    *slot->nh = 0;
    return disks_dispatch_h(ch, ops, ctx, slot->q, *slot->n, slot->hs, idl_nh, slot->r,
                          rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool disks_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t disks_serve_one(handle_t ch, const struct disks_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[DISKS_REQ_MAX];
    _Alignas(8) uint8_t idl_r[DISKS_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, DISKS_REQ_MAX, &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL) {
        idl_st = idl_drain(ch, idl_n, idl_nh);
    } else if (idl_st == OK) {
        handle_t idl_rhs[IDL_REP_HANDLES];
        uint32_t idl_rhn = 0;
        uint32_t idl_rn = disks_dispatch_h(ch, ops, ctx, idl_q, idl_n, idl_hs, idl_nh, idl_r,
                                         idl_rhs, &idl_rhn);
        if (!idl_rn)
            idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
        else   /* the reply's handles are gone whatever the write's status */
            (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    }
    return idl_st;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t disks_serve(handle_t ch, const struct disks_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[DISKS_REQ_MAX];
    _Alignas(8) uint8_t idl_r[DISKS_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES], idl_hs[IDL_READ_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = DISKS_REQ_MAX, .r = idl_r, .rhs = idl_rhs,
        .hs = idl_hs, .hcap = IDL_READ_HANDLES,
    };
    status_t idl_st;
    while ((idl_st = idl_serve_next(&idl_s)) == OK)
        idl_s.rn = disks_dispatch_h(ch, ops, ctx, idl_q, idl_s.n, idl_hs, idl_s.nh, idl_r,
                                  idl_rhs, &idl_s.rhn);
    return idl_st == ERR_PEER_CLOSED ? OK : idl_st;
}


/* ==== protocol `mounts` (id 73) =============================================
 *
 * mounts: what volumes sends on a watch channel (volumes.watch). The
 * events of one change all carry its generation, and `settled` ends it;
 * a new watch gets every mount there is with the current generation, then
 * `settled`. A generation is never 0, and a volumes that init started
 * again counts from somewhere else (the clock), so it is never taken for
 * the dead one's.
 *
 * A mount's channel stays the same across its service's restarts (they
 * are no change): a new channel comes with `unmounted` then `mounted` (a
 * remount, the ESP made writable and back, a service started again after
 * it was given up on). Init puts each in its namespace (/boot excepted)
 * and tells its followers at `settled`.
 *
 * Reconnect: ERR_PEER_CLOSED: volumes ended (every mount went with it), or
 * this watcher fell MOUNTS_UNREAD_MAX events behind; watch again. */

#define MOUNTS_PROTOCOL_ID 73u
#define MOUNTS_MOUNTED          0x00490001u
#define MOUNTS_UNMOUNTED        0x00490002u
#define MOUNTS_SETTLED          0x00490003u

/* Constants (the .idl's `const` lines). */
/* `mounted`'s flags. */
#define MOUNTS_READ_ONLY 1u
/* a test disk's: nobody's namespace wants it */
#define MOUNTS_TEST 2u
/* events a watcher may leave unread before it is dropped */
#define MOUNTS_UNREAD_MAX 256u

/* Messages (packed: no padding bytes ever cross the channel). */
struct mounts_mounted_msg {   /* an event: txid 0 */
    uint32_t txid;
    uint32_t ordinal;
    uint32_t generation;
    uint8_t flags;
} __attribute__((packed));
struct mounts_unmounted_msg {   /* an event: txid 0 */
    uint32_t txid;
    uint32_t ordinal;
    uint32_t generation;
} __attribute__((packed));
struct mounts_settled_msg {   /* an event: txid 0 */
    uint32_t txid;
    uint32_t ordinal;
    uint32_t generation;
} __attribute__((packed));

#define MOUNTS_REQ_MAX 8u   /* bytes: the biggest message to the server */
#define MOUNTS_REP_MAX 30u   /* bytes: the biggest message to the client */
#define MOUNTS_REQ_HANDLES IDL_READ_HANDLES   /* handles: read with each message to the server */
#define MOUNTS_REP_HANDLES IDL_REP_HANDLES   /* handles: room in a dispatch's rhs */

/* ---- client ---------------------------------------------------------- */

/* ---- client, asynchronous (tools/genidl.py) --------------------------- */

/* ---- events (one way, txid 0, never answered) -------------------------- */

/* A mount, and its `fs` channel (abi/idl/fs.idl): a duplicate of volumes'
 * client end, the watcher's to keep or close. */
/* The event mounts.mounted, to the client: written on ch, never answered.
 * ERR_SHOULD_WAIT: the peer's queue is full (its flow control).
 * The handles are gone in every case: sent, closed, or lost with a
 * write that failed (the caller never closes them after this). */
static inline status_t mounts_mounted(handle_t ch, const char *path, uint32_t path_len, uint32_t generation, uint8_t flags, handle_t fs)
{
    _Alignas(8) uint8_t idl_b0[30];
    struct mounts_mounted_msg *idl_q = (struct mounts_mounted_msg *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = 0;   /* an event */
    idl_q->ordinal = MOUNTS_MOUNTED;
    idl_q->generation = generation;
    idl_q->flags = flags;
    if (idl_st == OK && (!idl_put(idl_b0, &idl_qn, path, path_len, 15, 1) ||
                             !idl_str_ok(path, path_len)))
        idl_st = ERR_INVALID_ARGS;
    handle_t idl_hs[1];
    uint32_t idl_hn = 0;
    if (idl_st == OK) {
        idl_hs[idl_hn++] = fs;
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, idl_hs, idl_hn);
    } else {   /* never sent: the handles are still ours */
        if (fs != HANDLE_INVALID)
            drv_handle_close(fs);
    }
    return idl_st;
}

/* The mount `path` is gone: its channel is closed or about to be. */
/* The event mounts.unmounted, to the client: written on ch, never answered.
 * ERR_SHOULD_WAIT: the peer's queue is full (its flow control). */
static inline status_t mounts_unmounted(handle_t ch, const char *path, uint32_t path_len, uint32_t generation)
{
    _Alignas(8) uint8_t idl_b0[29];
    struct mounts_unmounted_msg *idl_q = (struct mounts_unmounted_msg *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = 0;   /* an event */
    idl_q->ordinal = MOUNTS_UNMOUNTED;
    idl_q->generation = generation;
    if (idl_st == OK && (!idl_put(idl_b0, &idl_qn, path, path_len, 15, 1) ||
                             !idl_str_ok(path, path_len)))
        idl_st = ERR_INVALID_ARGS;
    if (idl_st == OK)
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, NULL, 0);
    return idl_st;
}

/* The list is whole as of `generation`: tell the namespaces now. */
/* The event mounts.settled, to the client: written on ch, never answered.
 * ERR_SHOULD_WAIT: the peer's queue is full (its flow control). */
static inline status_t mounts_settled(handle_t ch, uint32_t generation)
{
    _Alignas(8) uint8_t idl_b0[12];
    struct mounts_settled_msg *idl_q = (struct mounts_settled_msg *)idl_b0;
    uint32_t idl_qn = sizeof(*idl_q);
    status_t idl_st = OK;
    idl_q->txid = 0;   /* an event */
    idl_q->ordinal = MOUNTS_SETTLED;
    idl_q->generation = generation;
    if (idl_st == OK)
        idl_st = drv_channel_write(ch, idl_b0, idl_qn, NULL, 0);
    return idl_st;
}

/* The client's handlers of the events from the server: a NULL one drops
 * its event (handles closed). A handler owns the handles it is given;
 * its arrays point into the message (copy what it keeps). */
struct mounts_events {
    void (*mounted)(void *ctx, const char *path, uint32_t path_len, uint32_t generation, uint8_t flags, handle_t fs);
    void (*unmounted)(void *ctx, const char *path, uint32_t path_len, uint32_t generation);
    void (*settled)(void *ctx, uint32_t generation);
};

/* Client: run the event read with idl_reply_read into msg and *m (an
 * event has txid 0, a reply any other): OK, its handler ran with its
 * handles; otherwise it is dropped, its handles closed:
 * ERR_NOT_SUPPORTED (no such event, or no handler), ERR_INVALID_ARGS
 * (it breaks the format, or isn't an event). */
static inline status_t mounts_event_dispatch(const struct mounts_events *idl_tab, void *ctx,
                                             const void *idl_m, struct idl_msg *m)
{
    uint32_t idl_n = m->n, idl_nh = m->nh;
    const handle_t *idl_hs = m->hs;
    m->nh = 0;   /* each path below takes them */
    if (idl_n < sizeof(struct idl_req_hdr) || ((const struct idl_req_hdr *)idl_m)->txid) {
        idl_close_all(idl_hs, idl_nh);
        return ERR_INVALID_ARGS;
    }
    switch (((const struct idl_req_hdr *)idl_m)->ordinal) {
    case MOUNTS_MOUNTED: {
        const struct mounts_mounted_msg *idl_e = (const struct mounts_mounted_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        const void *idl_p0 = NULL;
        uint32_t idl_l0 = 0;
        if (idl_st == OK && !idl_get(idl_m, idl_n, &idl_o, 15, 1, &idl_p0, &idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 1)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->mounted)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st == OK && !(idl_handle_is(idl_hs[0], IDL_OBJ_CHANNEL)))
            idl_st = ERR_WRONG_TYPE;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->mounted(ctx, (const char *)idl_p0, idl_l0, idl_e->generation, idl_e->flags, idl_hs[0]);
        return OK;
    }
    case MOUNTS_UNMOUNTED: {
        const struct mounts_unmounted_msg *idl_e = (const struct mounts_unmounted_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        const void *idl_p0 = NULL;
        uint32_t idl_l0 = 0;
        if (idl_st == OK && !idl_get(idl_m, idl_n, &idl_o, 15, 1, &idl_p0, &idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 0)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->unmounted)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->unmounted(ctx, (const char *)idl_p0, idl_l0, idl_e->generation);
        return OK;
    }
    case MOUNTS_SETTLED: {
        const struct mounts_settled_msg *idl_e = (const struct mounts_settled_msg *)idl_m;
        uint32_t idl_o = sizeof(*idl_e);
        status_t idl_st = idl_n < sizeof(*idl_e) ? ERR_INVALID_ARGS : OK;
        if (idl_o != idl_n)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && idl_nh != 0)
            idl_st = ERR_INVALID_ARGS;
        if (idl_st == OK && !idl_tab->settled)
            idl_st = ERR_NOT_SUPPORTED;
        if (idl_st != OK) {
            idl_close_all(idl_hs, idl_nh);
            return idl_st;
        }
        idl_tab->settled(ctx, idl_e->generation);
        return OK;
    }
    }
    idl_close_all(idl_hs, idl_nh);
    return ERR_NOT_SUPPORTED;
}

/* Client: read the next message on ch and run it as an event of the
 * server's (mounts_event_dispatch's results). ERR_SHOULD_WAIT: nothing is
 * queued; ERR_PEER_CLOSED: the server is gone; ERR_INTERNAL: a message
 * that is no event (a reply to a call that gave up), dropped. For a
 * channel whose replies come with idl_reply_read, call
 * mounts_event_dispatch for the messages with txid 0 instead. */
static inline status_t mounts_read_event(handle_t ch, const struct mounts_events *idl_tab, void *ctx)
{
    _Alignas(8) uint8_t idl_b[MOUNTS_REP_MAX];
    struct idl_msg idl_m;
    status_t idl_st = idl_reply_read(ch, idl_b, MOUNTS_REP_MAX, &idl_m);
    if (idl_st == OK && idl_m.txid) {
        idl_msg_drop(&idl_m);
        idl_st = ERR_INTERNAL;
    } else if (idl_st == OK) {
        idl_st = mounts_event_dispatch(idl_tab, ctx, idl_b, &idl_m);
    }
    return idl_st;
}

/* ---- server ---------------------------------------------------------- */

/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with mounts_reply_<method> (now, or later from anywhere). */
struct mounts_ops {
};

/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (MOUNTS_REP_MAX bytes) and the handles it carries
 * into rhs (MOUNTS_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the message has no txid, a `later` handler
 * answers it itself, or it has txid 0: an event of the other way, or
 * none, never answered). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it. */
static inline uint32_t mounts_dispatch_on(handle_t ch, const struct mounts_ops *ops, void *ctx,
                                          const void *req, uint32_t n, void *rep, handle_t *rhs,
                                          uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    (void)ops;
    (void)ctx;
    if (n < sizeof(struct idl_req_hdr) || !((const struct idl_req_hdr *)req)->txid) {
        /* txid 0: an event (or no txid): never answered */
        return 0;
    }
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* mounts_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t mounts_dispatch(const struct mounts_ops *ops, void *ctx, const void *req, uint32_t n,
                                       void *rep, handle_t *rhs, uint32_t *rhn)
{
    return mounts_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t mounts_take_slot(handle_t ch, const struct idl_slot *slot,
                                        struct idl_reply *rep)
{
    if (slot->qcap < MOUNTS_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by mounts_take_slot, or found there by a
 * successor), which came on ch: as mounts_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (MOUNTS_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it never sends it. */
static inline uint32_t mounts_run_slot(handle_t ch, const struct idl_slot *slot,
                                       const struct mounts_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return mounts_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool mounts_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t mounts_serve_one(handle_t ch, const struct mounts_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[MOUNTS_REQ_MAX];
    _Alignas(8) uint8_t idl_r[MOUNTS_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = mounts_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn)
        idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
    else   /* the reply's handles are gone whatever the write's status */
        (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t mounts_serve(handle_t ch, const struct mounts_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[MOUNTS_REQ_MAX];
    _Alignas(8) uint8_t idl_r[MOUNTS_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = mounts_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
